package com.smarthub.plus;

import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

public class SatelliteUiParserTest {
    private static final ZoneId BAGHDAD=ZoneId.of("Asia/Baghdad");
    private static long at(String time){return LocalDateTime.parse(time).atZone(BAGHDAD).toInstant().toEpochMilli();}
    private static Map<String,String> banner(){Map<String,String> m=new HashMap<>();m.put("tv_channel_info_index","0018");m.put("tv_channel_info_program_name","الـــــعـــــراقـــــيـــــة الـــــكـــــرديـــــة");return m;}
    @Test public void actualAurumBannerDoesNotTurnMissingEpgIntoAFilm(){Map<String,String> fields=banner();fields.put("mtv_info_current_epg_time",":الحالي");fields.put("mtv_info_current_epg","لا يوجد دليل البرامج الإلكتروني");fields.put("mtv_info_next_epg_time",":التالي");fields.put("mtv_info_next_epg","لا يوجد دليل البرامج الإلكتروني");SatelliteState s=SatelliteUiParser.parse(fields,at("2026-10-31T06:08:00"),BAGHDAD);assertEquals("Aurum:18",s.channelId);assertEquals("العراقية الكردية",s.channelName);assertEquals("",s.title);assertEquals("",s.nextTitle);assertEquals(0,s.startMs);assertEquals(0,s.nextStartMs);}
    @Test public void currentAndNextRangesCrossMidnightWithoutChangingTheFilmDay(){Map<String,String> f=banner();f.put("mtv_info_current_epg","The Film");f.put("mtv_info_current_epg_time","الحالي 23:20 – 00:50");f.put("mtv_info_next_epg","Next Film");f.put("mtv_info_next_epg_time","التالي 00:50 - 02:15");SatelliteState s=SatelliteUiParser.parse(f,at("2026-10-31T00:05:00"),BAGHDAD);assertEquals("The Film",s.title);assertEquals(at("2026-10-30T23:20:00"),s.startMs);assertEquals(at("2026-10-31T00:50:00"),s.endMs);assertEquals(s.endMs,s.nextStartMs);assertEquals(at("2026-10-31T02:15:00"),s.nextEndMs);}
    @Test public void arabicDigitsAndQualifiedViewIdsAreAccepted(){Map<String,String> f=new HashMap<>();f.put("com.tosmart.aurum:id/tv_channel_info_index","٠٠١٧");f.put("com.tosmart.aurum:id/tv_channel_info_program_name","قناة الأفلام");f.put("com.tosmart.aurum:id/mtv_info_current_epg","فيلم حقيقي");f.put("com.tosmart.aurum:id/mtv_info_current_epg_time","٠٩:٠٠ - ١١:٣٠");SatelliteState s=SatelliteUiParser.parse(f,at("2026-10-31T10:00:00"),BAGHDAD);assertEquals("Aurum:17",s.channelId);assertEquals(at("2026-10-31T09:00:00"),s.startMs);assertEquals("فيلم حقيقي",s.title);}
    @Test public void unrelatedScreensCannotReplaceTheCurrentChannel(){Map<String,String> f=new HashMap<>();f.put("random_name","Private other app text");f.put("mtv_info_current_epg","Any text");assertNull(SatelliteUiParser.parse(f,at("2026-10-31T10:00:00"),BAGHDAD));Map<String,String> foreign=new HashMap<>();foreign.put("other.app:id/tv_channel_info_index","1");foreign.put("other.app:id/tv_channel_info_program_name","Other app");assertNull(SatelliteUiParser.parse(foreign,at("2026-10-31T10:00:00"),BAGHDAD));}
    @Test public void aStaleCurrentEpgRangeIsNotAdvertisedAsCurrent(){Map<String,String> f=banner();f.put("mtv_info_current_epg","Yesterday film");f.put("mtv_info_current_epg_time","08:00 - 09:00");SatelliteState s=SatelliteUiParser.parse(f,at("2026-10-31T12:00:00"),BAGHDAD);assertEquals("",s.title);assertEquals(0,s.startMs);assertEquals(0,s.endMs);assertFalse(s.channelName.isEmpty());}
    @Test public void titleWithoutKnownTimesDoesNotGetInventedSchedule(){Map<String,String> f=banner();f.put("mtv_info_current_epg","Actual broadcast title");f.put("mtv_info_current_epg_time",":الحالي");f.put("mtv_info_next_epg","Future show");f.put("mtv_info_next_epg_time","التالي 00:30");SatelliteState s=SatelliteUiParser.parse(f,at("2026-10-31T23:45:00"),BAGHDAD);assertEquals("Actual broadcast title",s.title);assertEquals(0,s.startMs);assertEquals(0,s.endMs);assertEquals(at("2026-11-01T00:30:00"),s.nextStartMs);assertEquals(0,s.nextEndMs);}
    @Test public void missingAndExplicitMissingEpgAreDistinguished(){Map<String,String> f=banner();assertFalse(SatelliteUiParser.currentProvided(f,SatelliteUiParser.DEFAULT_PACKAGE));f.put("mtv_info_current_epg","");assertTrue(SatelliteUiParser.currentProvided(f,SatelliteUiParser.DEFAULT_PACKAGE));assertTrue(SatelliteUiParser.noEpg("لا يـوجـد دليل البرامج الإلكتروني"));assertTrue(SatelliteUiParser.noEpg("No programme information"));assertFalse(SatelliteUiParser.noEpg("The Programme"));}
    @Test public void expiryClearsProgrammeIdentityAndDoesNotPromoteUnconfirmedNext(){SatelliteState s=new SatelliteState();s.channelName="Channel";s.title="Old film";s.startMs=100;s.endMs=200;s.nextTitle="Old next film";s.nextStartMs=200;s.nextEndMs=300;s.expire(400);assertEquals("",s.title);assertEquals("",s.nextTitle);assertEquals("Channel",s.channelName);assertEquals(0,s.startMs);assertEquals(0,s.nextEndMs);}
}
